using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer.Tools;

[McpServerToolType]
public static class WeatherTool
{
    [McpServerTool, Description("Gets the current weather for a given city.")]
    public static string GetWeather(
        [Description("The city name to get weather for")] string city)
    {
        // Simulated weather data
        var temperature = Random.Shared.Next(-10, 35);
        return $"Weather in {city}: {temperature}°C, partly cloudy.";
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpHttpServer.Resources;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(
        Uri = "config://app/settings",
        Name = "App Configuration",
        Description = "Returns the current application configuration data.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = "Production",
            Features = new { EnableCaching = true, MaxConnections = 100 }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://app/settings/{section}",
        Name = "App Configuration Section",
        Description = "Returns a specific configuration section.")]
    public static string GetConfigSection(string section)
    {
        return section.ToLowerInvariant() switch
        {
            "database" => JsonSerializer.Serialize(new
            {
                ConnectionTimeout = 30,
                MaxPoolSize = 50,
                Provider = "PostgreSQL"
            }, new JsonSerializerOptions { WriteIndented = true }),

            "logging" => JsonSerializer.Serialize(new
            {
                Level = "Information",
                OutputFormat = "JSON",
                RetentionDays = 30
            }, new JsonSerializerOptions { WriteIndented = true }),

            _ => JsonSerializer.Serialize(new { Error = $"Unknown section: {section}" })
        };
    }
}

